export function tax(amount: number, region: string): number {
  if (!Object.hasOwn(TAX, region)) throw new Error(`unknown region: ${region}`);
  return amount * TAX[region];
}

/** Final total, rounded to cents at each money step (no float drift). */
export function total(items: Item[], region: string, c?: Coupon): number {
  const base = Math.round(items.reduce((s, i) => s + lineTotal(i), 0) * 100);
  const discounted = Math.round(applyCoupon(base / 100, c) * 100);
  const taxCents = Math.round(tax(discounted / 100, region) * 100);
  return (discounted + taxCents) / 100;
}

